from collections import Counter
def f(g):
    P=[[row[c:c+4] for row in g] for c in (0,5,10,15)]
    cnt=Counter(v for r in g for v in r if v)
    res=[]
    for i in range(4):
        row=[]
        for j in range(4):
            best=None;bc=99
            for p in P:
                v=p[i][j]
                if v and cnt[v]<bc: bc=cnt[v]; best=v
            row.append(best or 0)
        res.append(row)
    return res
